package com.usa.admin;
import com.b5.shared.*;import android.os.*;import android.content.*;import android.text.*;import android.widget.*;import android.graphics.Color;import com.google.firebase.database.*;import java.util.*;import java.security.SecureRandom;
public class MainActivity extends BrandActivity {
 Cloud cloud;boolean authorized=false,gate=false;DataSnapshot codes,users;LinearLayout codeRows,userRows;TextView stats;TextView[] metrics=new TextView[4];String query="";List<TextView> timers=new ArrayList<>();List<Long> expiries=new ArrayList<>();DatabaseReference codesRef,usersRef;ValueEventListener codesListener,usersListener;final SecureRandom random=new SecureRandom();
 @Override protected void begin(){if(!Cloud.configured(this)){Cloud.setup(this,this::begin);return;}try{cloud=new Cloud(this);login();}catch(Exception e){message(e.getMessage());Cloud.setup(this,this::begin);}}
 void login(){page("USA-Admin","Private control room • B5 premium");LinearLayout c=card();c.addView(text("Admin access",22,WHITE));EditText username=input(c,"Username",false),pin=input(c,"PIN",true);button(c,"Unlock dashboard",()->{if(!username.getText().toString().equals("admin")||!pin.getText().toString().equals("1234")){message("Incorrect admin login");return;}gate=true;if(cloud.auth.getCurrentUser()!=null&&!cloud.auth.getCurrentUser().isAnonymous())verifyAdmin();else firebaseLogin();});note(c,"admin / 1234 unlocks this device only. Firebase independently verifies your authorized administrator UID.");button(body,"Firebase settings",()->Cloud.setup(this,()->{message("Settings saved. Restart this app to reconnect.");}));footer();}
 void firebaseLogin(){page("Secure Firebase login","Use your Firebase administrator email/password account.");LinearLayout c=card();EditText mail=input(c,"Administrator email",false),pass=input(c,"Firebase password (not local PIN)",true);button(c,"Authenticate",()->cloud.auth.signInWithEmailAndPassword(mail.getText().toString().trim(),pass.getText().toString()).addOnSuccessListener(r->verifyAdmin()).addOnFailureListener(e->message(e.getMessage())));note(c,"Create this account in Firebase Authentication and add its UID under /admins in the Firebase Console. Never place admin credentials inside an APK.");button(c,"Back",this::login);}
 void verifyAdmin(){String uid=cloud.auth.getUid();cloud.root.child("admins").child(uid).get().addOnSuccessListener(s->{if(Boolean.TRUE.equals(s.getValue(Boolean.class))){authorized=true;dashboard();}else message("Not an authorized administrator. UID: "+uid);}).addOnFailureListener(e->message(e.getMessage()));}
 void dashboard(){detach();page("Command center","USA-FAVOR  /  LIVE OPERATIONS");String[] labels={"Total Codes","Active Users NOW","Expired Codes","Total Users Ever"};for(int i=0;i<4;i++){LinearLayout summary=card();summary.addView(text(labels[i],12,MUTED));metrics[i]=text("—",28,GOLD);summary.addView(metrics[i]);}stats=metrics[0];LinearLayout g=card();g.addView(text("Generate access",22,WHITE));Spinner duration=new Spinner(this);ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"1H","1D","7D","30D","LIFETIME"});duration.setAdapter(a);g.addView(duration);button(g,"＋ Generate USA code",()->generate(duration.getSelectedItem().toString()));EditText search=input(body,"Search code or Device ID",false);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int before,int count){query=s.toString().toUpperCase(Locale.US);render();}public void afterTextChanged(Editable e){}});
 body.addView(text("Active users & devices",23,WHITE));userRows=new LinearLayout(this);userRows.setOrientation(LinearLayout.VERTICAL);body.addView(userRows);body.addView(text("Access codes",23,WHITE));codeRows=new LinearLayout(this);codeRows.setOrientation(LinearLayout.VERTICAL);body.addView(codeRows);
 LinearLayout social=card();social.addView(text("Follow us • social links",21,WHITE));String[] names={"tiktok","instagram","youtube","telegram"};EditText[] fields=new EditText[4];for(int i=0;i<4;i++)fields[i]=input(social,names[i]+" HTTPS URL",false);cloud.root.child("config/socials").get().addOnSuccessListener(s->{for(int i=0;i<4;i++)fields[i].setText(Cloud.str(s,names[i]));});button(social,"Save social links",()->{Map<String,Object> map=new HashMap<>();for(int i=0;i<4;i++){String url=fields[i].getText().toString().trim();if(!url.isEmpty()&&!url.matches("https://[^\\s]+")){message("Social links must use HTTPS");return;}map.put(names[i],url);}cloud.root.child("config/socials").setValue(map).addOnSuccessListener(v->message("Social links saved")).addOnFailureListener(e->message(e.getMessage()));});button(body,"Sign out",()->{detach();authorized=false;cloud.auth.signOut();login();});footer();codesRef=cloud.root.child("codes");usersRef=cloud.root.child("users");codesListener=Cloud.listener(s->{codes=s;render();},this::message);usersListener=Cloud.listener(s->{users=s;render();},this::message);codesRef.addValueEventListener(codesListener);usersRef.addValueEventListener(usersListener);ui.removeCallbacks(tick);ui.post(tick);}
 final Runnable tick=new Runnable(){public void run(){if(!authorized||!alive)return;for(int i=0;i<timers.size();i++)timers.get(i).setText("Remaining: "+Policy.remaining(expiries.get(i),cloud.now()));updateStats();ui.postDelayed(this,1000);}};
 void generate(String duration){if(!cloud.clockReady){message("Waiting for Firebase server time");return;}createUnique(duration,0);}
 void createUnique(String duration,int tries){if(tries>10){message("Could not allocate unique code");return;}String chars="ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";StringBuilder b=new StringBuilder("USA-");for(int i=0;i<4;i++)b.append(chars.charAt(random.nextInt(chars.length())));String code=b.toString();Map<String,Object> map=new HashMap<>();map.put("duration",duration);map.put("used",false);map.put("createdAt",ServerValue.TIMESTAMP);map.put("isActive",false);cloud.root.child("codes").child(code).runTransaction(new Transaction.Handler(){public Transaction.Result doTransaction(MutableData data){if(data.getValue()!=null)return Transaction.abort();data.setValue(map);return Transaction.success(data);}public void onComplete(DatabaseError error,boolean committed,DataSnapshot s){if(error!=null)message(error.getMessage());else if(!committed)createUnique(duration,tries+1);else{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("USA-FAVOR code",code));message(code+" • "+duration+"\nCopied to clipboard");}}},false);}
 boolean match(DataSnapshot s){return query.isEmpty()||(s.getKey()+" "+Cloud.str(s,"deviceId")+" "+Cloud.str(s,"codeUsed")).toUpperCase(Locale.US).contains(query);}
 LinearLayout row(LinearLayout parent){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(16),dp(12),dp(16),dp(12));c.setBackground(shape(CARD,16));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(6),0,dp(6));parent.addView(c,p);return c;}
 void remaining(LinearLayout c,long n){TextView t=text("Remaining: "+Policy.remaining(n,cloud.now()),13,GOLD);c.addView(t);timers.add(t);expiries.add(n);}
 void render(){if(codeRows==null)return;timers.clear();expiries.clear();codeRows.removeAllViews();userRows.removeAllViews();if(users!=null)for(DataSnapshot s:users.getChildren()){if(!match(s))continue;LinearLayout c=row(userRows);boolean online=Cloud.yes(s,"isOnline");boolean fresh=cloud.now()-Cloud.num(s,"lastSeen")<120000;c.addView(text((online&&fresh?"● ONLINE":"● OFFLINE")+"  "+Cloud.str(s,"deviceModel"),16,online&&fresh?GREEN:MUTED));String id=s.getKey();note(c,"Device: "+id.substring(0,Math.min(12,id.length()))+"…\nCode: "+Cloud.str(s,"codeUsed")+"\nIP: "+Cloud.str(s,"ip")+"\nConnected: "+date(Cloud.num(s,"connectedAt"))+"\nLast seen: "+date(Cloud.num(s,"lastSeen")));if(codes!=null){DataSnapshot linked=codes.child(Cloud.str(s,"codeUsed"));if(linked.exists())remaining(c,Cloud.num(linked,"expiryAt"));}}
 if(codes!=null)for(DataSnapshot s:codes.getChildren()){if(!match(s))continue;LinearLayout c=row(codeRows);long expiry=Cloud.num(s,"expiryAt");String status=!Cloud.yes(s,"used")?"Not Used":Policy.expired(expiry,cloud.now())?"Expired":Cloud.yes(s,"isActive")?"Active":"Disabled";c.addView(text(s.getKey()+"  ·  "+Cloud.str(s,"duration"),18,GOLD));note(c,status+"\nDevice: "+Cloud.str(s,"deviceId"));if(Cloud.yes(s,"used"))remaining(c,expiry);button(c,"Extend +7 Days",()->extend(s.getKey()));button(c,"Delete code",()->new android.app.AlertDialog.Builder(this).setTitle("Delete "+s.getKey()+"?").setMessage("Linked device loses access when synchronized.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->s.getRef().removeValue().addOnFailureListener(e->message(e.getMessage()))).show());}updateStats();}
 void updateStats(){if(stats==null)return;long total=codes==null?0:codes.getChildrenCount(),all=users==null?0:users.getChildrenCount(),active=0,expired=0;if(users!=null)for(DataSnapshot s:users.getChildren())if(Cloud.yes(s,"isOnline")&&cloud.now()-Cloud.num(s,"lastSeen")<120000)active++;if(codes!=null)for(DataSnapshot s:codes.getChildren())if(Policy.expired(Cloud.num(s,"expiryAt"),cloud.now()))expired++;metrics[0].setText(""+total);metrics[1].setText(""+active);metrics[2].setText(""+expired);metrics[3].setText(""+all);}
 String date(long t){return t==0?"—":java.text.DateFormat.getDateTimeInstance().format(new Date(t));}
 void extend(String code){cloud.root.child("codes").child(code).runTransaction(new Transaction.Handler(){public Transaction.Result doTransaction(MutableData d){if(d.getValue()==null)return Transaction.abort();Boolean used=d.child("used").getValue(Boolean.class);if(!Boolean.TRUE.equals(used))return Transaction.abort();String dur=d.child("duration").getValue(String.class);if("LIFETIME".equals(dur))return Transaction.abort();Long x=d.child("expiryAt").getValue(Long.class);d.child("expiryAt").setValue(Policy.extended(x==null?0:x,cloud.now()));d.child("isActive").setValue(true);return Transaction.success(d);}public void onComplete(DatabaseError e,boolean committed,DataSnapshot s){if(e!=null)message(e.getMessage());else if(!committed)message("Only activated, finite-duration codes can be extended");}},false);}
 void detach(){if(codesRef!=null&&codesListener!=null)codesRef.removeEventListener(codesListener);if(usersRef!=null&&usersListener!=null)usersRef.removeEventListener(usersListener);ui.removeCallbacks(tick);}
 @Override protected void onDestroy(){detach();super.onDestroy();}
}
